import sys

def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    a = sorted(int(x) for x in data[2:2 + n])
    def ok(r):
        w = 2 * r
        cnt = 1
        end = a[0] + w
        for x in a:
            if x > end:
                cnt += 1
                if cnt > k:
                    return False
                end = x + w
        return True
    lo, hi = 0, (a[-1] - a[0] + 1) // 2
    while lo < hi:
        mid = (lo + hi) // 2
        if ok(mid):
            hi = mid
        else:
            lo = mid + 1
    print(lo)

main()

